  logPr $\leftarrow$ initialize ~vector ~with ~size ~$G_k.length()$\;
  n $\leftarrow$ total number of nodes\;
  $x_j \leftarrow$ choose (random) starting node $\in G_k$\;
  \BlankLine
  \emph{/* For each step, compute a random walk in $G_k$, and compare the probability to be in all the other $G$ */}\\
  \For {$s \leftarrow 1 \TO steps$} {
    \BlankLine
    \emph{/* Pick the next node of $G_k$ with random walk */}\\
    $x_k$ = next\_node( $G_k$, $x_j$ )\;
    \BlankLine
    \For {$i\leftarrow 0$ \KwTo $G.length()$} {
      $\left\langle k_{out}\right\rangle \leftarrow$ \texttt{get\_outdegree}($n_p$)\;
      \eIf {$\left\langle k_{out}\right\rangle == 0$} {
        logPr[ i ] $\leftarrow$ logPr[ i ] + $\log( 1 / n )$\;
      }{
        $p_i(x) = (1-\alpha) / n$\;
                  $Pd_{x_j} \leftarrow$ \texttt{get\_prob\_distribution}$(G_i,~x_j)$\;
                  $S_{x_j} \leftarrow$ \texttt{get\_successors}$(G_i,~x_j)$\;
        \If {$x_k \in S_{x_j}$} {
          $p_i(x) \leftarrow p_i(x) + \alpha * Pd_{x_j}(x_k)$\;
        }
        logPr[ i ] $\leftarrow$ logPr[ i ] + $\log( p_i(x) )$\;
      }
    }
  }
  \Return{}~logPr
\caption{\texttt{RandomSurfer}(k,~$\alpha$,~steps,~G)}\label{algo:randomsurfer}
